// Parse incoming request
const requestData = JSON.parse($input.first().json.body);

// Validate required fields
if (!requestData.text || !requestData.speakerId) {
  throw new Error('Missing required fields: text and speakerId');
}

// Prepare data for emotion analysis
const emotionAnalysisData = {
  text: requestData.text,
  speakerId: requestData.speakerId,
  conversationId: requestData.conversationId || 'default',
  context: {
    previousMessages: requestData.previousMessages || [],
    environment: requestData.environment || {},
    relationship: requestData.relationship || {},
    campaign: requestData.campaign || {},
    playerState: requestData.playerState || {}
  },
  timestamp: new Date().toISOString()
};

// Add metadata
emotionAnalysisData.metadata = {
  source: 'dialogue-system',
  version: '1.0',
  processingPriority: requestData.priority || 'normal'
};

return { json: emotionAnalysisData };

// Process emotion analysis results
const emotionResult = $input.first().json;

// Extract emotional state and metrics
const emotionalState = emotionResult.emotionalState || {};
const sentiment = emotionResult.sentiment || {};
const empathyResponse = emotionResult.empathyResponse || {};
const confidence = emotionResult.confidence || 0.5;

// Determine dominant emotion
const dominantEmotion = Object.entries(emotionalState)
  .sort((a, b) => b[1] - a[1])[0]?.[0] || 'neutral';

// Calculate emotional intensity
const emotionalIntensity = Object.values(emotionalState)
  .reduce((sum, intensity) => sum + intensity, 0) / Object.keys(emotionalState).length;

// Generate response strategy
const responseStrategy = determineResponseStrategy(dominantEmotion, emotionalIntensity, sentiment);

// Prepare context-aware response data
const responseData = {
  originalRequest: {
    text: emotionResult.originalText || '',
    speakerId: emotionResult.speakerId || '',
    timestamp: emotionResult.timestamp || new Date().toISOString()
  },
  emotionalAnalysis: {
    dominantEmotion,
    emotionalState,
    emotionalIntensity,
    confidence,
    sentiment,
    empathyResponse
  },
  responseStrategy,
  suggestedResponses: generateSuggestedResponses(dominantEmotion, emotionalIntensity, empathyResponse),
  metadata: {
    processedAt: new Date().toISOString(),
    processingTime: emotionResult.processingTime || 0,
    modelVersion: '1.0'
  }
};

function determineResponseStrategy(emotion, intensity, sentiment) {
  const strategies = {
    happiness: intensity > 0.7 ? 'enthusiastic' : 'supportive',
    sadness: intensity > 0.7 ? 'comforting' : 'supportive',
    anger: intensity > 0.7 ? 'deescalating' : 'understanding',
    fear: intensity > 0.7 ? 'reassuring' : 'supportive',
    surprise: intensity > 0.7 ? 'engaged' : 'acknowledging',
    disgust: intensity > 0.7 ? 'validating' : 'understanding',
    trust: 'reciprocal',
    anticipation: 'engaged',
    neutral: 'neutral'
  };

  return {
    primary: strategies[emotion] || 'neutral',
    intensity: intensity,
    sentimentAlignment: sentiment.score > 0 ? 'positive' : sentiment.score < 0 ? 'negative' : 'neutral',
    requiresEmpathy: empathyResponse !== null,
    confidence: confidence
  };
}

function generateSuggestedResponses(emotion, intensity, empathy) {
  const responseTemplates = {
    happiness: [
      "I can hear the excitement in your voice! Tell me more.",
      "That sounds wonderful! I'm genuinely happy for you.",
      "Your enthusiasm is contagious! What else happened?"
    ],
    sadness: [
      "I can hear how difficult this is for you. I'm here to listen.",
      "That sounds really tough. You don't have to go through this alone.",
      "I understand this hurts. Take your time to process this."
    ],
    anger: [
      "I can understand why you'd feel angry about this. Let's work through it.",
      "Your feelings are valid. What do you think would help right now?",
      "I hear your frustration. Let's find a constructive way forward."
    ],
    fear: [
      "That sounds scary. You're safe to talk about this with me.",
      "I understand your concern. Let's think through this together.",
      "Your fear makes sense given the situation. What would help you feel more secure?"
    ],
    neutral: [
      "I understand. Tell me more about that.",
      "Thank you for sharing that with me.",
      "How does that make you feel?"
    ]
  };

  const templates = responseTemplates[emotion] || responseTemplates.neutral;
  const responseCount = Math.min(3, Math.ceil(intensity * 3) + 1);

  return templates.slice(0, responseCount).map((template, index) => ({
    id: `response_${index + 1}`,
    text: template,
    appropriateness: 0.8 + (Math.random() * 0.2),
    emotionalTone: emotion,
    intensity: intensity
  }));
}

return { json: responseData };

// Generate analytics tracking data
const responseData = $input.first().json;
const originalRequest = responseData.originalRequest;
const emotionalAnalysis = responseData.emotionalAnalysis;
const responseStrategy = responseData.responseStrategy;

// Create analytics event
const analyticsEvent = {
  eventType: 'emotion_analysis_completed',
  timestamp: new Date().toISOString(),
  sessionId: originalRequest.speakerId,
  conversationId: originalRequest.speakerId,
  eventData: {
    dominantEmotion: emotionalAnalysis.dominantEmotion,
    emotionalIntensity: emotionalAnalysis.emotionalIntensity,
    confidence: emotionalAnalysis.confidence,
    sentimentScore: emotionalAnalysis.sentiment.score || 0,
    responseStrategy: responseStrategy.primary,
    requiresEmpathy: responseStrategy.requiresEmpathy,
    processingTime: responseData.metadata.processingTime
  },
  metadata: {
    workflowId: 'emotion-analysis-workflow',
    version: '1.0',
    source: 'dialogue-system'
  }
};

// Create performance metrics
const performanceMetrics = {
  sessionId: originalRequest.speakerId,
  processingMetrics: {
    emotionAnalysisTime: responseData.metadata.processingTime,
    totalProcessingTime: Date.now() - new Date(originalRequest.timestamp).getTime(),
    confidence: emotionalAnalysis.confidence,
    success: true
  },
  qualityMetrics: {
    emotionalAccuracy: emotionalAnalysis.confidence,
    responseRelevance: responseStrategy.confidence,
    empathyDetected: responseStrategy.requiresEmpathy
  }
};

return {
  json: {
    analyticsEvent,
    performanceMetrics,
    originalResponse: responseData
  }
};
